1	/*
2	 * heartbeat-sweep.ts -- Cloudflare Cron Trigger handler for the heartbeat sweep.
3	 *
4	 * Fired every 5 minutes by the every-5-minutes cron trigger in wrangler.toml.
5	 *
6	 * Design: instead of running the full Node-based heartbeatService.tickTimers()
7	 * (which depends on node:fs, node:child_process, and other Worker-incompatible
8	 * APIs to provision workspace directories), we perform only the scheduling query:
9	 *
10	 * 1. Select all active agents that have a heartbeat policy enabled and whose
11	 *    last heartbeat is older than policy.intervalSec seconds.
12	 * 2. For each due agent, enqueue a heartbeat_dispatch message to the
13	 *    PAPERCLIP_QUEUE which the queue consumer handles by starting a
14	 *    HeartbeatWorkflow Durable Object instance.
15	 *
16	 * The actual heartbeat execution (adapter invocation, workspace provisioning)
17	 * happens inside the HeartbeatWorkflow, which can delegate Node-only operations
18	 * to the sidecar process via HTTP.
19	 */
20	
21	import { eq } from "drizzle-orm";
22	import type { Db } from "@paperclipai/db";
23	import { agents, heartbeatRuns } from "@paperclipai/db";
24	import type { Env } from "../worker/api.js";
25	
26	/** Minimal heartbeat policy shape read from agent.heartbeatPolicy JSON. */
27	interface HeartbeatPolicy {
28	  enabled: boolean;
29	  intervalSec: number;
30	}
31	
32	function parseHeartbeatPolicy(agent: { heartbeatPolicy?: unknown }): HeartbeatPolicy {
33	  const policy = agent.heartbeatPolicy;
34	  if (!policy || typeof policy !== "object") {
35	    return { enabled: false, intervalSec: 0 };
36	  }
37	  const p = policy as Record<string, unknown>;
38	  const enabled = Boolean(p["enabled"]);
39	  const intervalSec = typeof p["intervalSec"] === "number" ? p["intervalSec"] : 0;
40	  return { enabled, intervalSec };
41	}
42	
43	/**
44	 * Runs the heartbeat sweep: finds agents that are due for a heartbeat based on
45	 * their configured interval, then enqueues `heartbeat_dispatch` messages for
46	 * each one. The queue consumer (`api.ts`) starts a `HeartbeatWorkflow` per message.
47	 *
48	 * @param env - The Worker Env bindings (provides `PAPERCLIP_QUEUE`).
49	 * @param db  - A Drizzle DB instance backed by Hyperdrive.
50	 */
51	export async function runHeartbeatSweep(env: Env, db: Db): Promise<void> {
52	  const now = new Date();
53	
54	  // Fetch all non-paused, non-terminated agents. We filter in-process rather
55	  // than in SQL to keep the query simple and avoid importing drizzle operators
56	  // beyond what's needed. The agent count is expected to be in the hundreds,
57	  // not millions, so a full table scan is acceptable here.
58	  const allAgents = await db
59	    .select({
60	      id: agents.id,
61	      companyId: agents.companyId,
62	      status: agents.status,
63	      heartbeatPolicy: agents.heartbeatPolicy,
64	      lastHeartbeatAt: agents.lastHeartbeatAt,
65	      createdAt: agents.createdAt,
66	    })
67	    .from(agents)
68	    .where(eq(agents.status, "active"));
69	
70	  const messagesToSend: Array<{
71	    agentId: string;
72	    companyId: string;
73	    runId: string;
74	    taskId?: string;
75	  }> = [];
76	
77	  for (const agent of allAgents) {
78	    const policy = parseHeartbeatPolicy(agent as { heartbeatPolicy?: unknown });
79	    if (!policy.enabled || policy.intervalSec <= 0) continue;
80	
81	    const baseline = new Date(agent.lastHeartbeatAt ?? agent.createdAt).getTime();
82	    const elapsedMs = now.getTime() - baseline;
83	    if (elapsedMs < policy.intervalSec * 1000) continue;
84	
85	    // Check if there is already a queued run for this agent to avoid double-
86	    // dispatching. We look for any run in "queued" status.
87	    const existingQueued = await db
88	      .select({ id: heartbeatRuns.id })
89	      .from(heartbeatRuns)
90	      .where(eq(heartbeatRuns.agentId, agent.id))
91	      .then((rows) =>
92	        rows.some(
93	          (r) =>
94	            (r as unknown as { status?: string }).status === "queued" ||
95	            (r as unknown as { status?: string }).status === "running",
96	        ),
97	      );
98	
99	    if (existingQueued) continue;
100	
101	    // Generate a run ID for the heartbeat workflow instance.
102	    const runId = crypto.randomUUID();
103	    messagesToSend.push({
104	      agentId: agent.id,
105	      companyId: agent.companyId,
106	      runId,
107	    });
108	  }
109	
110	  if (messagesToSend.length === 0) {
111	    console.log("[HeartbeatSweep] No agents due for heartbeat.");
112	    return;
113	  }
114	
115	  // Enqueue all messages. CF Queues supports batching up to 100 messages per call.
116	  const BATCH_SIZE = 100;
117	  for (let i = 0; i < messagesToSend.length; i += BATCH_SIZE) {
118	    const batch = messagesToSend.slice(i, i + BATCH_SIZE);
119	    await Promise.all(
120	      batch.map((msg) =>
121	        env.PAPERCLIP_QUEUE.send({
122	          type: "heartbeat_dispatch",
123	          agentId: msg.agentId,
124	          companyId: msg.companyId,
125	          runId: msg.runId,
126	          taskId: msg.taskId,
127	        }),
128	      ),
129	    );
130	  }
131	
132	  console.log(`[HeartbeatSweep] Dispatched ${messagesToSend.length} heartbeat(s).`);
133	}
